const ctaButtonBlock = defineBlock({
  type: "CTAButton",
  label: "Button",
  category: "content",
  icon: "mouse-pointer-click",
  defaultProps: {
    label: "Book now" as string,
    href: "/booking/vehicles" as string,
    variant: "gold" as "gold" | "white" | "outline",
    hoverLabel: "" as string,
    iconPosition: "none" as "none" | "before" | "after",
    background: "" as string,
    color: "" as string,
    borderStyle: "none" as "none" | "solid" | "dashed" | "dotted" | "double",
    borderWidth: "" as string,
    borderWidthTop: "" as string,
    borderWidthRight: "" as string,
    borderWidthBottom: "" as string,
    borderWidthLeft: "" as string,
    borderColor: "" as string,
    // Matches the pill shape variants already render via Tailwind's
    // rounded-full — persisted explicitly (not left empty) so the Style tab's
    // Border Radius field shows the button's real current value instead of
    // a misleading "0" that doesn't match what's actually on screen.
    borderRadius: "9999px" as string,
    borderRadiusTopLeft: "" as string,
    borderRadiusTopRight: "" as string,
    borderRadiusBottomRight: "" as string,
    borderRadiusBottomLeft: "" as string,
    boxShadow: "" as string,
    fontFamily: "inherit" as string,
    fontSize: "" as string,
    fontWeight: "600" as (typeof FONT_WEIGHT_VALUES)[number],
    textTransform: "none" as (typeof TEXT_TRANSFORM_VALUES)[number],
    fontStyle: "normal" as (typeof FONT_STYLE_VALUES)[number],
    textDecoration: "none" as (typeof TEXT_DECORATION_VALUES)[number],
    lineHeight: "" as string,
    letterSpacing: "" as string,
    wordSpacing: "" as string,
    textShadow: "" as string,
    paddingTop: "" as string,
    paddingRight: "" as string,
    paddingBottom: "" as string,
    paddingLeft: "" as string,
    hoverBackground: "" as string,
    hoverColor: "" as string,
    hoverBorderColor: "" as string,
    hoverBoxShadow: "" as string,
    // Animated "gradient slide" hover effect: when hoverBackgroundSize is
    // set, hoverBackground (which can be a gradient, not just a solid
    // color) applies to the button's normal/resting state instead of only
    // on :hover — oversized via background-size so hoverBackgroundPosition
    // has room to slide it into view on hover. Leaving hoverBackgroundSize
    // empty keeps the original behavior (hoverBackground only on :hover),
    // so every button saved before this existed renders identically.
    hoverBackgroundSize: "" as string,
    hoverBackgroundPosition: "" as string,
    hoverTransitionDuration: "" as string,
  },
  propsSchema: z.object({
    label: z.string().min(1),
    href: z.string().min(1),
    variant: z.enum(["gold", "white", "outline"]).default("gold"),
    // "none" hides the icon regardless of whether `icon` is set — lets a
    // user pick an icon once and toggle it on/off without losing the choice.
    iconPosition: z.enum(["none", "before", "after"]).default("none"),
    // Widened from `z.enum(ICON_NAMES)` — see the matching note on Divider's
    // `icon` field above.
    icon: z.string().optional(),
    // When set, hovering 3D-flips the button to reveal this text instead of `label`, then flips back on mouseleave.
    hoverLabel: z.string().optional(),
    // Every field below is applied inline directly on the button's own <a> —
    // never on the generic node.style wrapper. A wrapper-level background/
    // padding/border would sit *outside* the button's own already-opaque
    // Tailwind pill (see CTA_VARIANT_CLASSES), producing a visible second
    // box around it instead of restyling the button itself — the same
    // "double-div" failure mode noted on AnimatedBox, just for CSS instead
    // of GSAP. Any value set here overrides that block's Tailwind default;
    // unset fields fall through to the chosen `variant`.
    background: z.string().optional(),
    color: z.string().optional(),
    borderStyle: z.enum(["none", "solid", "dashed", "dotted", "double"]).default("none"),
    borderWidth: z.string().optional(),
    borderWidthTop: z.string().optional(),
    borderWidthRight: z.string().optional(),
    borderWidthBottom: z.string().optional(),
    borderWidthLeft: z.string().optional(),
    borderColor: z.string().optional(),
    borderRadius: z.string().optional(),
    borderRadiusTopLeft: z.string().optional(),
    borderRadiusTopRight: z.string().optional(),
    borderRadiusBottomRight: z.string().optional(),
    borderRadiusBottomLeft: z.string().optional(),
    boxShadow: z.string().optional(),
    fontFamily: z.string().default("inherit"),
    fontSize: z.string().optional(),
    fontWeight: z.enum(FONT_WEIGHT_VALUES).default("600"),
    textTransform: z.enum(TEXT_TRANSFORM_VALUES).default("none"),
    fontStyle: z.enum(FONT_STYLE_VALUES).default("normal"),
    textDecoration: z.enum(TEXT_DECORATION_VALUES).default("none"),
    lineHeight: z.string().optional(),
    letterSpacing: z.string().optional(),
    wordSpacing: z.string().optional(),
    textShadow: z.string().optional(),
    paddingTop: z.string().optional(),
    paddingRight: z.string().optional(),
    paddingBottom: z.string().optional(),
    paddingLeft: z.string().optional(),
    // True CSS :hover (not just Tailwind's static hover: utilities, which can't
    // see these runtime-set values — see the note on LayoutNodeStyle) — applied
    // via a small scoped <style> tag the component renders alongside itself.
    hoverBackground: z.string().optional(),
    hoverColor: z.string().optional(),
    hoverBorderColor: z.string().optional(),
    hoverBoxShadow: z.string().optional(),
    hoverBackgroundSize: z.string().optional(),
    hoverBackgroundPosition: z.string().optional(),
    hoverTransitionDuration: z.string().optional(),
  }),
});

