export const ICON_VIEW_VALUES = ["default", "stacked", "framed"] as const;
export const ICON_SHAPE_VALUES = ["square", "rounded", "circle"] as const;

const iconBlock = defineBlock({
  type: "Icon",
  label: "Icon",
  category: "content",
  icon: "star",
  defaultProps: {
    icon: "FaStar" as string,
    size: "32px" as string,
    color: "currentColor" as string,
    view: "default" as (typeof ICON_VIEW_VALUES)[number],
    shape: "circle" as (typeof ICON_SHAPE_VALUES)[number],
    linkUrl: "" as string,
    align: "center" as "left" | "center" | "right",
    hoverColor: "" as string,
    secondaryColor: "" as string,
    hoverSecondaryColor: "" as string,
    padding: "" as string,
    rotate: "" as string,
    borderRadiusTop: "" as string,
    borderRadiusRight: "" as string,
    borderRadiusBottom: "" as string,
    borderRadiusLeft: "" as string,
    // Framed view's border was hardcoded to 2px — width is now a real
    // field. Not adding a separate `borderColor`: `secondaryColor` already
    // fills that exact role for the Framed/Stacked shape (see the note
    // below), so a second field would just be a confusing duplicate.
    borderWidth: "" as string,
    borderWidthTop: "" as string,
    borderWidthRight: "" as string,
    borderWidthBottom: "" as string,
    borderWidthLeft: "" as string,
    boxShadow: "" as string,
  },
  propsSchema: z.object({
    // A react-icons/fa6 export name (e.g. "FaStar", "FaFacebook") chosen from
    // the searchable Icon Library, not a curated z.enum like CTAButton/Divider's
    // `icon` — the library has ~2000 names. Old pages saved before this change
    // used the small curated set (e.g. "star") — the renderer falls back to
    // that set when a name isn't found in react-icons, so nothing breaks.
    icon: z.string().default("FaStar"),
    size: z.string().default("32px"),
    color: z.string().optional(),
    view: z.enum(ICON_VIEW_VALUES).default("default"),
    shape: z.enum(ICON_SHAPE_VALUES).default("circle"),
    linkUrl: z.string().optional(),
    align: z.enum(["left", "center", "right"]).default("center"),
    hoverColor: z.string().optional(),
    // Stacked/Framed views draw the icon glyph over a background shape —
    // secondaryColor is that shape's fill (Stacked) / border (Framed), same
    // Normal/Hover split as CTAButton's own background/border colors.
    secondaryColor: z.string().optional(),
    hoverSecondaryColor: z.string().optional(),
    padding: z.string().optional(),
    rotate: z.string().optional(),
    borderRadiusTop: z.string().optional(),
    borderRadiusRight: z.string().optional(),
    borderRadiusBottom: z.string().optional(),
    borderRadiusLeft: z.string().optional(),
    borderWidth: z.string().optional(),
    borderWidthTop: z.string().optional(),
    borderWidthRight: z.string().optional(),
    borderWidthBottom: z.string().optional(),
    borderWidthLeft: z.string().optional(),
    boxShadow: z.string().optional(),
  }),
});

