// ── Itinerary Roadmap ────────────────────────────────────────────────────
// A winding-road "trip timeline" — a top-down vehicle graphic travels along
// an SVG path as the visitor scrolls, with a card per stop alternating
// left/right (see Route.png). Started life as a one-off homepage section
// (apps/web's MotionPathScrollBinder.tsx + a hardcoded RichText itinerary
// template) and a standalone demo route (app/timeline-demo); this is the
// real, reusable, admin-editable version of the same idea — a normal block
// draggable onto any page, any number of times.

const itineraryRoadmapItemSchema = z.object({
  time: z.string(),
  heading: z.string(),
  description: z.string(),
  position: z.enum(["left", "right"]),
});
export type ItineraryRoadmapItem = z.infer<typeof itineraryRoadmapItemSchema>;

export const ITINERARY_TRIGGER_MODE_VALUES = ["scroll", "timeline"] as const;

// A two-bend S-curve in an 800×800 box, confined to a narrow central lane
// (x from 260 to 540, i.e. roughly 32.5%–67.5% of the box) rather than
// bulging out to the box's edges — the original version (Route.png's
// layout, x from 150 to 650) left cards positioned at the container's own
// edges with nowhere to sit that didn't overlap the road at typical
// container widths. The vertical straight segments (100/300/500/700) and
// bend spacing are unchanged; only the horizontal bulge amount shrank, via
// an elliptical (rx=70, not rx=ry=100) arc instead of a true semicircle —
// ry stays 100 to exactly span the unchanged 200-unit vertical gap between
// each pair of bend points, while rx=70 controls how far it bulges
// sideways.
const DEFAULT_ROAD_PATH_D =
  "M 330 100 L 470 100 A 70 100 0 0 1 470 300 L 330 300 A 70 100 0 0 0 330 500 L 470 500 A 70 100 0 0 1 470 700 L 330 700";

