// ── Dynamic Collection binding ─────────────────────────────────────────
// Renders items from a `Collection` (see schema.prisma) as a grid/list.
// Which fields of each item map to which visual slot is intentionally left
// out of scope for this pass — see the Step 3/4 plan.

const collectionListBlock = defineBlock({
  type: "CollectionList",
  label: "Collection List",
  category: "collection",
  icon: "database",
  defaultProps: { collectionKey: "" as string, layout: "grid" as "grid" | "list", limit: 12 as number, columns: 3 as number },
  propsSchema: z.object({
    collectionKey: z.string().min(1),
    layout: z.enum(["grid", "list"]).default("grid"),
    limit: z.number().int().positive().max(100).default(12),
    columns: z.number().int().min(1).max(4).default(3),
  }),
});

// ── Marquee Strip ─────────────────────────────────────────────────────────
// Was a `legacySection` (singleton, self-fetching a single `HomeContent.
// marqueeText` string with no styling control) — promoted to a real block so
// admins can list multiple distinct ticker items and style them per-instance
// like any other block. `items` cycles end-to-end to fill the scrolling
// strip; odd/even index alternates the pill/plain look, matching the
// original design.

const marqueeStripBlock = defineBlock({
  type: "MarqueeStrip",
  label: "Marquee Strip",
  category: "section",
  icon: "layout-template",
  defaultProps: {
    items: ["Web Design", "Branding", "Development", "Strategy"] as string[],
    showIcon: true as boolean,
    speedSeconds: 22 as number,
    gap: "1.5rem" as string,
    background: "" as string,
    color: "" as string,
    pillBackground: "" as string,
    pillColor: "" as string,
    fontSize: "" as string,
    fontWeight: "600" as (typeof FONT_WEIGHT_VALUES)[number],
  },
  propsSchema: z.object({
    items: z.array(z.string()).default(["Web Design", "Branding", "Development", "Strategy"]),
    showIcon: z.boolean().default(true),
    speedSeconds: z.number().positive().default(22),
    gap: z.string().default("1.5rem"),
    background: z.string().optional(),
    color: z.string().optional(),
    pillBackground: z.string().optional(),
    pillColor: z.string().optional(),
    fontSize: z.string().optional(),
    fontWeight: z.enum(FONT_WEIGHT_VALUES).default("600"),
  }),
});

