// ── Tours Grid (Static) ─────────────────────────────────────────────────
// A curated card grid with the same layout/style prop set a live-data
// listing would use, except every card's content is a plain per-instance
// item, hand-entered rather than fetched — editing one instance never
// affects any other page using this block.
const staticTourItemSchema = z.object({
  image: z.string().optional(),
  title: z.string().optional(),
  tagline: z.string().optional(),
  description: z.string().optional(),
  maxPeople: z.string().optional(),
  durationLabel: z.string().optional(),
  price: z.string().optional(),
  href: z.string().optional(),
});
export type StaticTourItem = z.infer<typeof staticTourItemSchema>;

