// ── Testimonials ─────────────────────────────────────────────────────────
// Was a `legacySection` — promoted the same way as Services/TrustHighlights.
// Reviews themselves stay self-fetched from GET /api/reviews (already a
// real, separately admin-editable content type via the Reviews page) —
// only the surrounding copy and every visual style are per-instance props.
// The Google/Trustpilot/Tripadvisor cards, previously a hardcoded const with
// no admin control at all (not even a link), are a real repeatable list.

const testimonialPlatformItemSchema = z.object({
  name: z.string(),
  href: z.string().optional(),
  rating: z.string().optional(),
  viewReviewsLabel: z.string().optional(),
  icon: z.enum(["google", "trustpilot", "tripadvisor"]).default("google"),
});
export type TestimonialPlatformItem = z.infer<typeof testimonialPlatformItemSchema>;

