// Was a `legacySection` — promoted the same way as Services/TrustHighlights.
// Questions are a real per-instance list (not self-fetched from the global
// /api/faqs list like an earlier version of this block did) — each page
// using this block gets its own independent FAQ set, since different pages
// need different questions. Reuses the question*/answer*/card* field names
// AccordionItem already established for the identical concept (an
// expandable Q&A row).

const faqItemSchema = z.object({
  question: z.string(),
  answer: z.string(),
});
export type FaqItem = z.infer<typeof faqItemSchema>;

const DEFAULT_FAQ_ITEMS: FaqItem[] = [
  {
    question: "How do I get started on a project with Marwa Digital?",
    answer:
      "Reach out through our contact page with a bit about your goals and timeline. We'll set up a short discovery call, scope the work together, and send over a proposal — most projects kick off within a week or two of that first conversation.",
  },
  {
    question: "What services does Marwa Digital offer?",
    answer:
      "We handle web design, branding, web development, SEO & content, e-commerce, and product design — either as standalone engagements or as a full end-to-end build, depending on what your project needs.",
  },
  {
    question: "Are your project prices fixed, and are there hidden fees?",
    answer:
      "Yes. Every proposal includes a fixed price for the agreed scope before any work begins, so there are no surprise charges partway through. If your needs grow beyond the original scope, we'll always discuss and agree on it with you first.",
  },
  {
    question: "What happens if my project timeline needs to change?",
    answer:
      "Life happens — if you need to adjust a deadline or pause a project, just let your point of contact know as early as possible and we'll work with you to find a new timeline that fits.",
  },
  {
    question: "What does your team actually deliver at the end of a project?",
    answer:
      "Every engagement ends with a fully working, well-documented product — source files, credentials, and a short handoff walkthrough — so you own everything and aren't locked into needing us for basic changes.",
  },
  {
    question: "Can I hire Marwa Digital for a custom, one-off project outside your standard packages?",
    answer:
      "Absolutely. Our packages are a starting point — if your project doesn't fit neatly into one, reach out and we'll scope a custom plan around exactly what you need.",
  },
  {
    question: "What is the cancellation policy for an ongoing project?",
    answer:
      "We offer flexible cancellation — you can pause or end an engagement with written notice, and you'll only be billed for work already completed. Reach out to your point of contact anytime to discuss.",
  },
];

