// ── Legacy sections ──────────────────────────────────────────────────────
// A handful of whole-section/whole-page blocks that still self-fetch their
// own content rather than reading `props` — so they can be inserted,
// removed, and reordered on the canvas today, but not given independent
// per-instance content until they're refactored to accept props. Tracked as
// `singleton: true` so the admin canvas can grey out their property panel
// instead of pretending edits do something.

const emptyPropsSchema = z.object({});

function legacySection(type: string, label: string): BlockRegistryEntry<Record<string, never>> {
  return defineBlock({
    type,
    label,
    category: "section",
    icon: "layout-template",
    singleton: true,
    defaultProps: {},
    propsSchema: emptyPropsSchema,
  });
}

const legacyBlocks = [
  legacySection("SiteFooter", "Site Footer"),
  // Whole-page wrappers used only as the starting point when a core route
  // (Contact) is converted to the builder — each is the exact JSX that page
  // already renders today (see apps/web/src/components/builder/legacyPages.tsx),
  // so converting doesn't change anything visually until the admin starts editing.
  legacySection("ContactPageLegacy", "Contact Page (current design)"),
  // The working contact form on its own — submits to the same ContactInquiry
  // pipeline (apps/admin's Inquiries list) as the legacy whole-page version
  // above. Used to decompose the Contact page into real, independently
  // editable blocks without touching the submission handling, which isn't
  // itself prop-driven content.
  legacySection("ContactFormBlock", "Contact Form"),
];

