// ── Creative widgets ─────────────────────────────────────────────────────
// Each block below is intentionally independent — its own item schema, its
// own defaultProps/propsSchema, no shared base type with its siblings, even
// where two blocks look superficially similar (e.g. IconBullets vs. the
// existing IconList) — matching a single distinct widget per block, not a
// configurable multi-purpose one.

