// ── Payments & Integrations ──────────────────────────────────────────────
// Real link-out buttons, not a checkout SDK — `paymentLink` is a URL an
// admin pastes in from their own PayPal.me link or a Stripe Payment Link
// (both are no-code, no-API-key hosted checkout pages the provider
// generates from their own dashboard), so clicking the button actually
// takes a visitor to a real place to pay instead of doing nothing. Building
// a full embedded checkout (server-side session creation, webhooks, a real
// API key round-trip) is a separate, much larger integration this
// deliberately doesn't attempt.

