// Consolidates "Basic Posts" and "Posts" — same shell, no separate simplified variant.
// Fetches real published posts (see PostsBlock.tsx in apps/web) — `columns`/
// `itemCount`/`showExcerpt`/`showDate`/`cardBackground`/`titleColor` all
// still drive the *built-in default* card (used whenever `loopTemplateId`
// is empty or its template can't be found); `loopTemplateId` optionally
// points at a `blog_loop_item` SiteTemplate — a custom card design an admin
// built once in Theme Builder — which then gets repeated once per post
// instead, with each repetition's own real post data (same
// admin-references-a-SiteTemplate-by-id shape as the `Template` block's
// own `templateId`, not a `z.enum` — the picker itself lives in
// PropertyPanel.tsx, fetched client-side since the choices are dynamic
// admin content, not a fixed list).
const postsBlock = defineBlock({
  type: "Posts",
  label: "Posts",
  category: "collection",
  icon: "newspaper",
  defaultProps: {
    columns: "3" as string,
    itemCount: "3" as string,
    showExcerpt: true as boolean,
    showDate: true as boolean,
    cardBackground: "" as string,
    titleColor: "" as string,
    loopTemplateId: "" as string,
  },
  propsSchema: z.object({
    columns: z.string().default("3"),
    itemCount: z.string().default("3"),
    showExcerpt: z.boolean().default(true),
    showDate: z.boolean().default(true),
    cardBackground: z.string().optional(),
    titleColor: z.string().optional(),
    loopTemplateId: z.string().optional(),
  }),
});

