// block above — reused deliberately so this stays a genuine table, not a
// rigid 5-named-field row shape only good for this one use case) plus a
// centered CTA button. Every visual cluster (card, eyebrow, heading,
// description, table header row, table body rows, CTA button) is
// var-bridged (see STYLE_KEYS in styleKeys.ts + the render component) so
