// ── Featured Routes Carousel ────────────────────────────────────────────
// Eyebrow + heading + description header, a "sub-label" line, prev/next
// scroll arrows, a horizontally-scrollable row of route cards (image +
// badge + title + description + Read More/Book Now footer, same footer
// shape as the Services carousel), with the CENTER card fixed as visually
// "active" (border + slightly larger image) — deliberately decoupled from
// scroll position (scrolling the row never moves which card is
// highlighted, since there's nothing to page to/from that a true
// single-focus carousel would have). Prev/Next just scrolls the row by one
// card width (native overflow-x, no custom paging state) since all cards
// are meant to be reachable by simple scrolling, not swapped in/out a
// fixed number of slots.
const routeCardItemSchema = z.object({
  image: z.string().optional(),
  badge: z.string().optional(),
  title: z.string().optional(),
  description: z.string().optional(),
  readMoreUrl: z.string().optional(),
  bookNowUrl: z.string().optional(),
  // Meta/price row — a typical listing-card shape (Max N / duration
  // + "From €price" + a full "View Details" pill). maxPeople/durationLabel/price are plain
  // strings, not numbers — e.g. "8" or "Up to 4 Hours" — same free-text
  // convention as every other per-item field on this card.
  maxPeople: z.string().optional(),
  durationLabel: z.string().optional(),
  price: z.string().optional(),
});
export type RouteCardItem = z.infer<typeof routeCardItemSchema>;

const DEFAULT_ROUTE_CARDS: RouteCardItem[] = [
  { image: "", badge: "FEATURED", title: "Brand Identity Refresh", description: "A full visual identity system, built to scale across every touchpoint.", readMoreUrl: "", bookNowUrl: "", durationLabel: "", price: "" },
  { image: "", badge: "FEATURED", title: "E-Commerce Storefront", description: "A fast, conversion-focused storefront rebuilt from the ground up.", readMoreUrl: "", bookNowUrl: "", durationLabel: "", price: "" },
  { image: "", badge: "FEATURED", title: "Product Launch Campaign", description: "Web, content, and paid strategy for a new product launch.", readMoreUrl: "", bookNowUrl: "", durationLabel: "", price: "" },
  { image: "", badge: "FEATURED", title: "SaaS Marketing Site", description: "A high-performing marketing site that converts trial signups.", readMoreUrl: "", bookNowUrl: "", durationLabel: "", price: "" },
  { image: "", badge: "FEATURED", title: "Content & SEO Program", description: "An ongoing content engine driving steady organic growth.", readMoreUrl: "", bookNowUrl: "", durationLabel: "", price: "" },
];

