// A reusable "definition list" section: a repeatable list of label + rich
// HTML content rows laid out two-column (label left / content right, e.g.
// "Data Controller" / the paragraph explaining it) — the shape used by
// Privacy Policy / Terms-style legal content, but generic enough for any
// label+detail layout. `content` (and `intro`/`footerNote`) accept raw HTML
// — same trust boundary as Faq's answer / IconList's text elsewhere in this
// file — so an admin can paste a <ul> bullet list, <a href="mailto:...">
// links, or even a full <table> for a row like "Legal Basis for Processing"
// without needing a dedicated table-editing UI (the shared RichTextEditor's
// tiptap instance has no table extension).
