// ── Checklist ─────────────────────────────────────────────────────────────
// "Inclusions & Exclusions" card: eyebrow + title header, two columns
// (Included / Excluded) each with a pill-style label and a checkmark/cross
// bullet list, and a centered CTA button. Each column's items are plain
// strings (StringListEditor, not SimpleRepeaterEditor) — every item in a
// column shares the same fixed icon (check for Included, cross for
// Excluded), so there's no per-item sub-field to edit beyond the text
// itself, same shape as ServiceCard's "Features" list.
