export function getBlockDefinition(type: string): BlockRegistryEntry | undefined {
  return BLOCK_REGISTRY[type];
}

export function listBlocksByCategory(category: BlockCategory): BlockRegistryEntry[] {
  return Object.values(BLOCK_REGISTRY).filter((b) => b.category === category);
}
